import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import crypto from 'node:crypto';

const page = await (await fetch('http://127.0.0.1:9222/json/new?about:blank', { method: 'PUT' })).json();
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let serial = 0;
const pending = new Map(), exceptions = [], failed = [];
ws.onmessage = ({ data }) => {
  const message = JSON.parse(data);
  if (message.method === 'Runtime.exceptionThrown') exceptions.push(message.params.exceptionDetails);
  if (message.method === 'Network.responseReceived' && message.params.response.status >= 400 && !message.params.response.url.endsWith('/favicon.ico')) failed.push(message.params.response.url);
  if (pending.has(message.id)) {
    const { resolve, reject } = pending.get(message.id); pending.delete(message.id);
    message.error ? reject(Error(JSON.stringify(message.error))) : resolve(message.result);
  }
};
/** Executa um comando no Chrome isolado, com timeout para não bloquear a sessão. */
function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++serial; const timer = setTimeout(() => { pending.delete(id); reject(Error('Tempo excedido: ' + method)); }, 25000);
    pending.set(id, { resolve: value => { clearTimeout(timer); resolve(value); }, reject: error => { clearTimeout(timer); reject(error); } });
    ws.send(JSON.stringify({ id, method, params }));
  });
}
/** Consulta a fixture ou o jogo local, devolvendo erros de execução explicitamente. */
async function evaluate(expression) {
  const response = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (response.exceptionDetails) throw Error(JSON.stringify(response.exceptionDetails));
  return response.result.value;
}

try {
 await send('Runtime.enable');await send('Page.enable');await send('Network.enable');
 await send('Emulation.setDeviceMetricsOverride',{width:1280,height:850,deviceScaleFactor:1,mobile:false});
 await send('Page.navigate',{url:process.env.PILOT_REVIEW_URL+'/docs/diario-ia/qa/perseguicao-20261020/props.html'});
 let ready=false;for(let i=0;i<240;i++){if(await evaluate('Boolean(window.propsReview)')){ready=true;break;}await new Promise(r=>setTimeout(r,100));}assert.ok(ready,'Painel deve carregar.');
 const models=await evaluate(`(async()=>{const c=propsReview,T=await import('/src/vendor/three/three.module.js');return Object.keys(c.prototypes).map(id=>{const a=c.prototypes[id].create(),b=c.prototypes[id].create(),box=new T.Box3().setFromObject(a);let calls=0,shared=true;const aa=[],bb=[];a.traverse(o=>{if(o.isMesh)aa.push(o);});b.traverse(o=>{if(o.isMesh)bb.push(o);});aa.forEach((o,i)=>{calls++;if(o.geometry!==bb[i].geometry||o.material!==bb[i].material)shared=false;});return {id,size:box.getSize(new T.Vector3()).toArray(),minY:box.min.y,calls,shared};});})()`);
 assert.equal(models.length,15);for(const m of models){assert.ok(m.size.every(x=>x>.15),m.id);assert.ok(Math.abs(m.minY)<.001,m.id+': apoio');assert.ok(m.shared&&m.calls<=6,m.id+': compartilhamento');}
 for(const id of ['teddy','robot','duck','drum','jack','armchair','rocking-horse','table']){
  await evaluate(`document.querySelector('#prop').value='${id}';new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))`);
  const shot=await send('Page.captureScreenshot',{format:'png'});await fs.writeFile('/tmp/legendgirl-rota-'+id+'.png',Buffer.from(shot.data,'base64'));
 }
 const continuity=await evaluate(`(()=>{const r=propsReview.room,decor=r.room.decorations,before=decor.map(o=>({id:o.uuid,p:o.position.toArray(),kind:o.userData.propId})),count=r.resources.size;
 for(let s=0;s<=720;s+=.5){r.room.update(s);}
 return {before,after:decor.map(o=>({id:o.uuid,p:o.position.toArray(),kind:o.userData.propId})),count,afterCount:r.resources.size};})()`);
 assert.deepEqual(continuity.before,continuity.after,'Nenhum móvel pode mudar de identidade ou posição durante o avanço.');assert.equal(continuity.count,continuity.afterCount);assert.ok(continuity.count<300,'Orçamento de recursos deve permanecer abaixo de 300.');
 for(const distance of [42,82,148,225,290,420,555,680]){
  await evaluate(`document.querySelector('#distance').value='${distance}';new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))`);
  const shot=await send('Page.captureScreenshot',{format:'png'});await fs.writeFile('/tmp/legendgirl-rota-percurso-'+distance+'.png',Buffer.from(shot.data,'base64'));
 }
 await evaluate('propsReview.dispose()');
 await send('Page.navigate',{url:process.env.PILOT_REVIEW_URL+'/?debug=1'});
 for(let i=0;i<160;i++){if(await evaluate('Boolean(window.game?.startDebugPhase)'))break;await new Promise(r=>setTimeout(r,100));}
 await evaluate(`document.querySelector('#debug-phase-select').value='bear-chase';document.querySelector('#debug-phase-select').dispatchEvent(new Event('change',{bubbles:true}));`);
 ready=false;for(let i=0;i<240;i++){const c=await evaluate('(()=>{const c=game.state.toyRoomInstance?.instance.chase;return {ready:c?.ready,error:c?.error}})()');if(c.error)throw Error(c.error);if(c.ready){ready=true;break;}await new Promise(r=>setTimeout(r,100));}assert.ok(ready);
 await evaluate('game.setPaused(true)');
 const captures=[];
 for(const [width,height]of [[1280,800],[390,844],[844,390]]){
  await send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:width<900});
  for(const distance of [82,225,290,420,555,720]){
   const metrics=await evaluate(`(()=>{const c=game.state.toyRoomInstance.instance.chase;Object.assign(c.state,{stage:'RUNNING',distance:${distance},time:25,age:25,x:0,gap:23});c.render();return {resources:c.renderer.resources.size,calls:c.renderer.renderer.info.render.calls,girl:c.renderer.girl.position.toArray(),camera:c.renderer.camera.position.toArray()};})()`);
   assert.ok(metrics.resources<300);assert.ok(metrics.calls<310,'Chamadas devem respeitar baseline: '+JSON.stringify(metrics));
   const shot=await send('Page.captureScreenshot',{format:'png'}),file='/tmp/legendgirl-rota-jogo-'+width+'-'+distance+'.png';await fs.writeFile(file,Buffer.from(shot.data,'base64'));captures.push({width,height,distance,...metrics});
  }
 }
 const full=await evaluate(`(async()=>{const {createChaseState,stepChase,restoreChaseState}=await import('/src/js/bear-chase/ChaseSimulation.js');const {routeFrame,ROUTE_AMBUSHES}=await import('/src/js/bear-chase/ChaseRoute.js');let results=[];
 for(const difficulty of ['NORMAL','EASY']){const state=createChaseState();let frames=0,throws=0;while(state.stage!=='COMPLETE'&&frames++<15000){const near=state.obstacles.filter(o=>o.z>=state.distance-.5).sort((a,b)=>a.z-b.z)[0];let target=0;if(near){const group=state.obstacles.filter(o=>Math.abs(o.z-near.z)<.01&&!o.hit);const safe=[-2.4,0,2.4].filter(x=>group.every(o=>Math.abs(x-o.x)>1.1));target=safe.sort((a,b)=>Math.abs(a-state.x)-Math.abs(b-state.x))[0]??0;}const input=Math.max(-1,Math.min(1,(target-state.x)*4));throws+=stepChase(state,input,1/60,difficulty).filter(e=>e.type==='toyThrown').length;if(frames===4000){const copy=restoreChaseState(state);if(JSON.stringify(copy)!==JSON.stringify(state))throw Error('Save deve restaurar o estado integral.');}}
 results.push({difficulty,stage:state.stage,hits:state.hits,frames,throws});}return results;})()`);
 for(const result of full){assert.equal(result.stage,'COMPLETE');assert.equal(result.hits,0,'Percurso deve permitir desviar de todos os grupos: '+JSON.stringify(result));}
 const disposed=await evaluate(`(()=>{const r=game.state.toyRoomInstance.instance.chase.renderer;r.destroy();r.destroy();return r.resources.size;})()`);assert.equal(disposed,0);
 assert.deepEqual(exceptions,[]);assert.deepEqual(failed,[]);
 console.log('APROVADO: 15 modelos, sala fixa, recursos estáveis, três formatos, curvas/morros, conclusão sem colisão NORMAL/EASY e descarte.',JSON.stringify({models,resources:continuity.count,full,captures}));
}finally{ws.close();await fetch('http://127.0.0.1:9222/json/close/'+page.id);}
